_choice_tag() {
    local tags
    tags="$(_argc_util_path_search_parent tags)"
    [[ -n $tags ]] || return 0
    gawk -F '\t' '!/^!_TAG_/ && NF >= 2 { print $1 "\t" $2 }' "$tags"
}

_choice_terminal() {
    command -v toe >/dev/null 2>&1 || return 0
    toe -a 2>/dev/null | gawk -F '\t' 'NF >= 2 { print $1 "\t" $2; next } NF { print $1 }'
}

_choice_vimrc() {
